            listPresence: (args: { projectId: Id<"projects"> }) => Promise<Array<{ cursorPosition: { x: number; y: number } | null; editingNodeId?: string; lastHeartbeat: number; selectedNodeId?: string; sessionId: string; userColor: string; userId: string; userName: string }>>;
